CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, duty VARCHAR(120) DEFAULT '', phone VARCHAR(30) DEFAULT '',
  role ENUM('admin','staff','exec','worker','citizen') NOT NULL, cell VARCHAR(80) DEFAULT '', `user` VARCHAR(60) NOT NULL UNIQUE,
  pass VARCHAR(255) NOT NULL, age TINYINT UNSIGNED NULL, status VARCHAR(30) DEFAULT '', sex VARCHAR(10) DEFAULT '', village VARCHAR(80) DEFAULT '', isibo VARCHAR(80) DEFAULT '', photo VARCHAR(200) DEFAULT '', must_change TINYINT NOT NULL DEFAULT 0, email VARCHAR(120) NULL, at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(role,cell)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cells(name VARCHAR(80) PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS news(id INT AUTO_INCREMENT PRIMARY KEY, t VARCHAR(200), b TEXT, cell VARCHAR(80) DEFAULT '', uid INT, aud VARCHAR(40) NOT NULL DEFAULT 'staff,exec,citizen', comments_on TINYINT NOT NULL DEFAULT 0, sectors VARCHAR(200) NOT NULL DEFAULT '', file VARCHAR(200) DEFAULT '', at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS news_views(news_id INT NOT NULL, uid INT NOT NULL, at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(news_id,uid), FOREIGN KEY(news_id) REFERENCES news(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS news_comments(id INT AUTO_INCREMENT PRIMARY KEY, news_id INT NOT NULL, uid INT, u VARCHAR(120), role VARCHAR(20), room VARCHAR(10) NOT NULL DEFAULT 'staff', kind VARCHAR(10) NOT NULL DEFAULT 'text', b TEXT, file VARCHAR(200) DEFAULT '', at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(news_id), FOREIGN KEY(news_id) REFERENCES news(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS services(id INT AUTO_INCREMENT PRIMARY KEY, cell VARCHAR(80) DEFAULT '', name VARCHAR(200), d TEXT, req TEXT, fee VARCHAR(100), hours VARCHAR(100), uid INT, at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fb(id INT AUTO_INCREMENT PRIMARY KEY, uid INT, u VARCHAR(120), cell VARCHAR(80), k VARCHAR(30), b TEXT, file VARCHAR(200) DEFAULT '', reply TEXT NULL, rby VARCHAR(120) NULL, reply_at TIMESTAMP NULL DEFAULT NULL, at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(cell), INDEX(uid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reports(id INT AUTO_INCREMENT PRIMARY KEY, uid INT, u VARCHAR(120), t VARCHAR(200), b TEXT, file VARCHAR(200) DEFAULT '', at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS meets(id INT AUTO_INCREMENT PRIMARY KEY, t VARCHAR(200), a VARCHAR(10), live TINYINT DEFAULT 0, starts DATETIME NULL, at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `log`(id INT AUTO_INCREMENT PRIMARY KEY, u VARCHAR(120), w VARCHAR(300), at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS villages(id INT AUTO_INCREMENT PRIMARY KEY, cell VARCHAR(80) NOT NULL, name VARCHAR(80) NOT NULL, UNIQUE(cell,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS isibo(id INT AUTO_INCREMENT PRIMARY KEY, village_id INT NOT NULL, name VARCHAR(80) NOT NULL, UNIQUE(village_id,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS chat(id INT AUTO_INCREMENT PRIMARY KEY, uid INT NOT NULL, u VARCHAR(120), role VARCHAR(20), b TEXT, at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, edited TINYINT NOT NULL DEFAULT 0, deleted TINYINT NOT NULL DEFAULT 0, upd TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, sec VARCHAR(30) NOT NULL DEFAULT '') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_attempts(id INT AUTO_INCREMENT PRIMARY KEY, ident VARCHAR(80) NOT NULL, ip VARCHAR(45) NOT NULL, at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(ident,at), INDEX(ip,at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
